import 'package:flutter/material.dart';

/// Guided capture shell for the supplied ANM/ASHA proforma.
/// Field definitions preserve the supplied form; clinical interpretation is not performed here.
class AntenatalQuestionnaireScreen extends StatefulWidget {
  const AntenatalQuestionnaireScreen({super.key});
  @override State<AntenatalQuestionnaireScreen> createState()=>_AntenatalQuestionnaireScreenState();
}
class _AntenatalQuestionnaireScreenState extends State<AntenatalQuestionnaireScreen>{
 final PageController page=PageController(); int step=0;
 final Map<String,TextEditingController> values={};
 final sections=<String,List<String>>{
 'Personal details':['Patient name','Age','Degree','Occupation','Husband name','Husband age','Husband degree','Husband occupation','Consumption habits','Family income','Socioeconomic status','Address','Nearest health centre','Transportation method','Time taken to reach','Distance from residence','Blood group'],
 'Menstrual & current pregnancy':['Gravida (Primi / Multi)','G','P','A','L','LMP','Previous cycles (regular / irregular)','EDD','POG','Booking & immunization details'],
 'Presenting complaints':['Presenting complaint','History of presenting complaints'],
 'First trimester':['Conception (spontaneous / induced)','Pregnancy confirmation','Days of amenorrhoea','UPT / USG done','Place','Number of antenatal visits','Remarks in antenatal visits','Folic acid supplements','History of hyperemesis','Fever with rashes','Bleeding PV','Radiation exposure','Bladder habits','Pain during micturition','Drug intake','Dating scan with place','Dating scan remarks'],
 'Second trimester':['Number of antenatal visits','Remarks in antenatal visits','TT immunization with place','Number of doses and POG','Quickening','Iron and calcium supplements','Bleeding PV','Leaking PV','Symptoms of preeclampsia','Oedema','DIPSI','Result of DIPSI','Anomaly scan','Anomaly scan remarks'],
 'Third trimester':['Number of antenatal visits','Remarks in antenatal visits','Iron and calcium supplements','Fetal movements','Symptoms of preeclampsia','Bleeding PV','Leaking PV','Pain in abdomen','Bladder and bowel disturbances'],
 'Menstrual & marital history':['Age at menarche','Menstrual cycles','Days between cycles','Cycles lasting for','Flow','Clots','Dysmenorrhoea','Married for','Consanguinity','Degree'],
 'Past medical, personal, diet & family history':['Jaundice / HTN / DM / thyroid / epilepsy / asthma / TB / other','Past surgeries (except LSCS)','Past hospitalisations','Blood transfusions','STD','Drug / other allergies','Sleep','Appetite','Addictions','Bowel & bladder habits','Diet (mixed / vegetarian)','24-hour recall','Calorie and protein intake adequacy','Congenital anomalies in family','Multiple pregnancies in family','Abortions in family','Chronic disorders in family'],
 };
 @override void dispose(){for(final c in values.values){c.dispose();}page.dispose();super.dispose();}
 TextEditingController controller(String key)=>values.putIfAbsent(key,()=>TextEditingController());
 @override Widget build(BuildContext context){final names=sections.keys.toList();return Scaffold(appBar:AppBar(title:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisSize:MainAxisSize.min,children:[const Text('Maternal Assessment'),Text('Section ${step+1} of ${names.length}',style:const TextStyle(fontSize:12,fontWeight:FontWeight.normal))])),body:Column(children:[LinearProgressIndicator(value:(step+1)/names.length,color:const Color(0xFFA61932),backgroundColor:const Color(0xFFF2DDE1),minHeight:5),Expanded(child:PageView.builder(controller:page,itemCount:names.length,onPageChanged:(v)=>setState(()=>step=v),physics:const NeverScrollableScrollPhysics(),itemBuilder:(context,index){final section=names[index];return ListView(padding:const EdgeInsets.all(18),children:[Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xFFFFE8EC),Color(0xFFFFF8F8)]),borderRadius:BorderRadius.circular(20)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(section,style:const TextStyle(fontSize:21,fontWeight:FontWeight.bold,color:Color(0xFF6F1428))),const SizedBox(height:6),const Text('Complete the available information. Unknown or unasked items should not be guessed.',style:TextStyle(color:Colors.black54))]),),const SizedBox(height:16),...sections[section]!.map((field)=>Padding(padding:const EdgeInsets.only(bottom:13),child:TextField(controller:controller('$section::$field'),decoration:InputDecoration(labelText:field,border:OutlineInputBorder(borderRadius:BorderRadius.circular(14)),filled:true,fillColor:Colors.white),textCapitalization:TextCapitalization.sentences,maxLines:field.toLowerCase().contains('address')||field.toLowerCase().contains('remarks')||field.toLowerCase().contains('recall')?3:1))),if(section=='Past medical, personal, diet & family history')const Text('Past obstetric history, delivery, baby and abortion details are captured as repeatable records in their dedicated workflow.',style:TextStyle(color:Colors.black54))]);})),Padding(padding:const EdgeInsets.all(16),child:Row(children:[OutlinedButton(onPressed:step==0?null:()=>page.previousPage(duration:const Duration(milliseconds:250),curve:Curves.easeOut),child:const Text('Back')),const Spacer(),FilledButton(style:FilledButton.styleFrom(backgroundColor:const Color(0xFFA61932)),onPressed:()=>step==names.length-1?_showReview():page.nextPage(duration:const Duration(milliseconds:250),curve:Curves.easeOut),child:Text(step==names.length-1?'Review':'Continue'))]))]));}
 void _showReview()=>showDialog(context:context,builder:(c)=>AlertDialog(title:const Text('Assessment captured'),content:const Text('This screen currently holds the questionnaire draft locally in memory. Connect the authenticated save-and-sync service before using it for real patient records.'),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Close'))]));
}
